import{_ as i,o as u,c as n,a2 as l}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Utaratibu wa Ufunguo wa Rasilimali za Uozi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/18-修炼资源开放机制.md","filePath":"sw/18-修炼资源开放机制.md","lastUpdated":null}'),o={name:"sw/18-修炼资源开放机制.md"};function m(t,a,w,s,h,e){return u(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="utaratibu-wa-ufunguo-wa-rasilimali-za-uozi" tabindex="-1">Utaratibu wa Ufunguo wa Rasilimali za Uozi <a class="header-anchor" href="#utaratibu-wa-ufunguo-wa-rasilimali-za-uozi" aria-label="Permalink to &quot;Utaratibu wa Ufunguo wa Rasilimali za Uozi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>18</td></tr><tr><td>Moduli</td><td>Sheria za Ulimwengu na Mifumo ya Uozi</td></tr><tr><td>Maneno Muhimu</td><td>Ufunguo wa Rasilimali, Rasilimali za Uozi, Mfumo wa Mgawanyo, Kupinga Monopoli, Haki ya Rasilimali</td></tr></tbody></table><h2 id="_1-mazingira-na-umuhimu-wa-utaratibu-wa-ufunguo-wa-rasilimali-za-uozi" tabindex="-1">1. Mazingira na Umuhimu wa Utaratibu wa Ufunguo wa Rasilimali za Uozi <a class="header-anchor" href="#_1-mazingira-na-umuhimu-wa-utaratibu-wa-ufunguo-wa-rasilimali-za-uozi" aria-label="Permalink to &quot;1. Mazingira na Umuhimu wa Utaratibu wa Ufunguo wa Rasilimali za Uozi&quot;">​</a></h2><p>Katika enzi ya uwindaji, rasilimali za uozi zilikuwa ndiyo jambo la msingi la mashindano. Mishipa ya roho, mashamba ya dawa, mishipa ya madini ya nishati, hazina za mbingu, maeneo ya siri ya uozi, na rasilimali nyingine zilikuwa zinakabiliwa na watu wachache wenye nguvu na madhehebu, na watu wa chini walikuwa karibu hawepati rasilimali za kawaida za uozi. Monopoli hii ya rasilimali haiku sababisha tu uti wa mgongo wa tabaka tulivu, bali pia ilisababisha vita na mauaji mengi yanayotokana na mashindano ya rasilimali. Monopoli wa rasilimali ni msingi wa kiuchumi wa mfumo wa uwindaji — mada rasilimali zinakabiliwa na watu wachache, &quot;kila mtu ana njia&quot; itaendelea kuwa ni maneno matupu tu.</p><p>Baada ya uundwaji wa Utamaduni wa Usawa wa Neo, &quot;ufunguo wa rasilimali za uozi&quot; ulichukuliwa kama moja ya mabadiliko ya msingi ya kitaifa. Lengo la msingi la utaratibu wa ufunguo wa rasilimali za uozi ni: kuvunja monopoli ya rasilimali, kuhakikisha kila maisha inaweza kupata rasilimali za msingi za uozi, na kwa wakati huo huo kushawishi matumizi yenye ufanisi na uumbaji wa endelevu wa rasilimali kupitia mfumo wa mgawanyo wa &quot;kazi nyingi faida nyingi&quot;. Ufunguo wa rasilimali haumaanishi &quot;mgawanyo sawa wa rasilimali&quot;, bali &quot;upatikanaji wa haki wa rasilimali&quot; — chini ya masharti ya kuhakikisha mahitaji ya msingi, mgawanyo wa rasilimali unahusishwa na mchango wa mtu binafsi, na kwa wakati huo huo kila aina ya monopoli ya rasilimali inakatazwa kali.</p><p>Umuhimu wa utaratibu wa ufunguo wa rasilimali za uozi uko katika: inatenganisha mchanga wa uwindaji kutoka msingi wa kiuchumi, inatoa uhakika wa vitu kwa uenezi halisi wa mifumo tatu mia ya uozi, inatoa msaada wa rasilimali kwa lengo la kijamii la &quot;kila mtu ana njia&quot;, na inalenga kuanzisha hatua ya haki kwa maendeleo ya pamoja ya kabila zote.</p><h2 id="_2-uainishaji-na-viwango-vya-rasilimali-za-uozi" tabindex="-1">2. Uainishaji na Viwango vya Rasilimali za Uozi <a class="header-anchor" href="#_2-uainishaji-na-viwango-vya-rasilimali-za-uozi" aria-label="Permalink to &quot;2. Uainishaji na Viwango vya Rasilimali za Uozi&quot;">​</a></h2><h3 id="_2-1-uainishaji-wa-rasilimali" tabindex="-1">2.1 Uainishaji wa Rasilimali <a class="header-anchor" href="#_2-1-uainishaji-wa-rasilimali" aria-label="Permalink to &quot;2.1 Uainishaji wa Rasilimali&quot;">​</a></h3><p>Rasilimali za uozi katika Heng Yuan Zhou zimegawanywa katika makundi makuu yafuatayo kulingana na asili na matumizi:</p><table tabindex="0"><thead><tr><th>Aina ya Rasilimali</th><th>Maudhui Mahususi</th><th>Matumizi ya Kuu</th></tr></thead><tbody><tr><td>Rasilimali za Nishati</td><td>Mishipa ya roho, mishipa ya madini ya nishati, kristali za nishati ya roho, vipande vya nishati ya asili, n.k.</td><td>Kutoa pembejeo ya nishati inayohitajika kwa uozi</td></tr><tr><td>Rasilimali za Dawa</td><td>Dawa za roho, mimea ya milele, vifaa vya utengenezaji wa vidonge, vidonge vilivyokamilika, n.k.</td><td>Kusaidia uozi, kutibu majeraha, kuvunja vizuizi</td></tr><tr><td>Rasilimali za Vifaa</td><td>Vyombo vya uozi, vyombo vya sheria, vifaa vya kuzidisha, vifaa vya nafasi, n.k.</td><td>Kuongeza ufanisi wa uozi, kusaidia udhibiti wa sheria</td></tr><tr><td>Rasilimali za Nafasi</td><td>Maeneo ya siri ya uozi, maeneo ya msongamano wa nishati ya roho, vyumba vya ufahamu wa sheria, nafasi zilizotengwa, n.k.</td><td>Kutoa mazingira maalum ya uozi</td></tr><tr><td>Rasilimali za Maarifa</td><td>Mbinu za uozi, uzoefu wa uozi, nyenzo za utafiti wa sheria, nyaraka za teknolojia, n.k.</td><td>Kutoa mwongozo wa nadharia na mbinu kwa uozi</td></tr><tr><td>Rasilimali za Kibaolojia</td><td>Wanyama wa roho, mimea ya roho, maisha ya mkataba, viumbe vya usawa, n.k.</td><td>Kutoa msaada wa uozi, mzunguko wa usawa, uwezo wa pekee</td></tr><tr><td>Rasilimali za Ulimwengu</td><td>Mazingira yasiyojengwa, haki za matumizi ya njia za ulimwengu, vipande vya kiini cha ulimwengu, n.k.</td><td>Kutoa nafasi ya uozi na maendeleo ya kiwango kikubwa</td></tr></tbody></table><h3 id="_2-2-viwango-vya-rasilimali" tabindex="-1">2.2 Viwango vya Rasilimali <a class="header-anchor" href="#_2-2-viwango-vya-rasilimali" aria-label="Permalink to &quot;2.2 Viwango vya Rasilimali&quot;">​</a></h3><p>Rasilimali zote za uozi zimegawanywa katika viwango vitano kulingana na nadra na thamani:</p><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Nadra</th><th>Njia ya Mgawanyo</th></tr></thead><tbody><tr><td>Kiwango cha 1</td><td>Rasilimali za Kawaida</td><td>Zimeenea sana, hazina nyingi</td><td>Ufunguo wa bure au mgawanyo wa bei nafuu</td></tr><tr><td>Kiwango cha 2</td><td>Rasilimali za Bora</td><td>Za kawaida kiasi, hazina wastani</td><td>Mgawanyo wa msingi + ubadilishaji wa mchango</td></tr><tr><td>Kiwango cha 3</td><td>Rasilimali za Nadra</td><td>Nadra kiasi, hazina mdogo</td><td>Ubadilishaji wa mchango + idhini ya ombi</td></tr><tr><td>Kiwango cha 4</td><td>Rasilimali za Epik</td><td>Nadra sana, hazina ndogo sana</td><td>Mgawanyo wa ushindani + kipaumbele kwa miradi ya kiwango cha utamaduni</td></tr><tr><td>Kiwango cha 5</td><td>Rasilimali za Hadithi</td><td>Nadra mno, karibu zimepotea</td><td>Mgawanyo maalum wa chuo cha juu cha maamuzi cha utamaduni</td></tr></tbody></table><h2 id="_3-kanuni-za-msingi-za-ufunguo-wa-rasilimali" tabindex="-1">3. Kanuni za Msingi za Ufunguo wa Rasilimali <a class="header-anchor" href="#_3-kanuni-za-msingi-za-ufunguo-wa-rasilimali" aria-label="Permalink to &quot;3. Kanuni za Msingi za Ufunguo wa Rasilimali&quot;">​</a></h2><h3 id="_3-1-kanuni-ya-uhakikisho-wa-msingi" tabindex="-1">3.1 Kanuni ya Uhakikisho wa Msingi <a class="header-anchor" href="#_3-1-kanuni-ya-uhakikisho-wa-msingi" aria-label="Permalink to &quot;3.1 Kanuni ya Uhakikisho wa Msingi&quot;">​</a></h3><p>Kila maisha ina haki ya kupata rasilimali za kiwango cha 1 na cha 2 zinazohitajika kudumisha uozi wa msingi. Rasilimali za uhakikisho wa msingi zinagawanywa bure au kwa bei nafuu kupitia &quot;Mfumo wa Uhakikisho wa Kila Mtu Ana Njia&quot;, bila vizuizi, bila ubaguzi. Kiwango cha uhakikisho wa msingi kinarekebishwa mara kwa mara na Bunge la Jamhuri ya Kila Kabila kulingana na hali ya rasilimali na hatua ya maendeleo ya utamaduni, kuhakikisha kiwango cha uhakikisho kinalingana na uwezo wa kubeba wa utamaduni.</p><h3 id="_3-2-kanuni-ya-kazi-nyingi-faida-nyingi" tabindex="-1">3.2 Kanuni ya Kazi Nyingi Faida Nyingi <a class="header-anchor" href="#_3-2-kanuni-ya-kazi-nyingi-faida-nyingi" aria-label="Permalink to &quot;3.2 Kanuni ya Kazi Nyingi Faida Nyingi&quot;">​</a></h3><p>Juu ya uhakikisho wa msingi, mgawanyo wa rasilimali za kiwango cha 3 na juu unachukua thamani ya mchango wa mtu binafsi kwa mtandao wa usawa kama msingi kuu. Kadiri mchango unavyozidi, rasilimali zinazoweza kubadilishwa huongezeka na kiwango hupanda. Kanuni ya kazi nyingi faida nyingi inawashawishi waozaji kujitahidi kuinua kiwango chao na kutoa mchango mkubwa zaidi kwa utamaduni, na kwa wakati huo huo inahakikisha rasilimali zinamtiririka kwa watu binafsi na vikundi wenye uwezo wa kuzitumia kwa ufanisi zaidi.</p><h3 id="_3-3-kanuni-ya-kupinga-monopoli" tabindex="-1">3.3 Kanuni ya Kupinga Monopoli <a class="header-anchor" href="#_3-3-kanuni-ya-kupinga-monopoli" aria-label="Permalink to &quot;3.3 Kanuni ya Kupinga Monopoli&quot;">​</a></h3><p>Inakatazwa kali kwa mtu yeyote binafsi, shirika, au kabila kuishi na rasilimali za uozi. Hatua mahususi za kupinga monopoli zinajumuisha:</p><ul><li>Rasilimali za kiwango cha 3 na juu zinazomilikiwa na mtu binafsi au shirika moja hazifai kuzidi 1% ya jumla ya hazina ya utamaduni</li><li>Inakatazwa kuhifadhi kwa ajili ya udaladala — wenye rasilimali hawafai kuhifadhi kwa uonevu na kuinua bei wakati rasilimali zikiwa haba</li><li>Inakatazwa umiliki wa kipekee — rasilimali za umma (kama vile mishipa ya roho ya umma, maeneo ya siri ya umma, n.k.) hazifai kuamilikiwa kwa kipekee na watu binafsi | Tabia zinazovunja sheria ya kupinga monopoli zitapigwa risasi kali na Mahakama ya Neo, ikiwa ni pamoja na kukamata rasilimali, kufuta thamani ya mchango, kupunguza ruhusa za uozi, n.k.</li></ul><h3 id="_3-4-kanuni-ya-matumizi-ya-endelevu" tabindex="-1">3.4 Kanuni ya Matumizi ya Endelevu <a class="header-anchor" href="#_3-4-kanuni-ya-matumizi-ya-endelevu" aria-label="Permalink to &quot;3.4 Kanuni ya Matumizi ya Endelevu&quot;">​</a></h3><p>Ukuzaji na matumizi ya rasilimali zote lazima yafuate kanuni ya endelevu, na hauruhusiwi kuchimba kwa uwindaji wa aina ya &quot;kukausha bwawa kupata samaki&quot;. Mahitaji mahususi yanajumuisha:</p><ul><li>Kasi ya ukuzaji wa rasilimali haifai kuzidi kasi ya kuzaliwa upya wa asili wa rasilimali (kwa rasilimali zisizoweza kuzaliwa upya, inahitajika kuandaa mpango mbadala)</li><li>Ukuzaji wa rasilimali lazima ufanywe tathmini ya athari ya mazingira, kuzuia uharibifu usioweza kurejelewa kwa mfumo wa ikolojia</li><li>Kwa rasilimali zizo hatarini kutoweka, kutekelezwa sera ya kuzuia kuchimba au kupunguza kuchimba, kulinda uwezo wa kuzaliwa upya wa rasilimali</li><li>Kushawishi kilimo cha kiwango cha kiwandani na usanifu wa rasilimali za nadra kupitia njia za teknolojia (kama vile uhandisi wa sheria, teknolojia ya kuzidisha, n.k.) kupunguza utegemezi wa rasilimali za asili</li></ul><h3 id="_3-5-kanuni-ya-ufunguo-na-uwazi" tabindex="-1">3.5 Kanuni ya Ufunguo na Uwazi <a class="header-anchor" href="#_3-5-kanuni-ya-ufunguo-na-uwazi" aria-label="Permalink to &quot;3.5 Kanuni ya Ufunguo na Uwazi&quot;">​</a></h3><p>Mchakato wa mgawanyo wa rasilimali lazima uwe wazi na uwazi, na ukubali ufuatiliaji wa maisha yote:</p><ul><li>Hazina, mgawanyo, na hali ya ukuzaji wa rasilimali zote za umma zinafichuliwa kwa jamii mara kwa mara</li><li>Viwango, michakato, na matokeo ya mgawanyo wa rasilimali ni vazi na vinapatafshwa</li><li>Kuweka mfumo wa maombi ya mgawanyo wa rasilimali, ambapo watu binafsi wenye pingamizi dhidi ya matokeo ya mgawanyo wanaweza kuomba tathmini upya</li><li>&quot;Kamiti ya Haki ya Rasilimali&quot; chini ya Mahakama ya Neo, inatutikia hasa ufuatiliaji wa haki na kisheria wa mgawanyo wa rasilimali</li></ul><h2 id="_4-mitataba-mahususi-ya-ufunguo-wa-rasilimali" tabindex="-1">4. Mitataba Mahususi ya Ufunguo wa Rasilimali <a class="header-anchor" href="#_4-mitataba-mahususi-ya-ufunguo-wa-rasilimali" aria-label="Permalink to &quot;4. Mitataba Mahususi ya Ufunguo wa Rasilimali&quot;">​</a></h2><h3 id="_4-1-mfumo-wa-mikataba-ya-uzalishaji-pamoja" tabindex="-1">4.1 Mfumo wa Mikataba ya Uzalishaji Pamoja <a class="header-anchor" href="#_4-1-mfumo-wa-mikataba-ya-uzalishaji-pamoja" aria-label="Permalink to &quot;4.1 Mfumo wa Mikataba ya Uzalishaji Pamoja&quot;">​</a></h3><p>Mkataba wa uzalishaji pamoja ni muundo wa msingi wa ufunguo wa rasilimali za uozi, na njia yake ya msingi ya utendaji imeelezwa kwa undani katika hati &quot;Kanuni ya Mgawanyo wa Kazi Nyingi Faida Nyingi&quot;. Katika uwanja wa ufunguo wa rasilimali, matumizi mahususi ya mkataba wa uzalishaji pamoja yanajumuisha:</p><ul><li><strong>Mkataba wa Mishipa ya Roho</strong>: Kutoa mishipa ya roho ya umma kwa vikundi vya waozaji au jumuiya za kabila kwa mkataba, ambapo mwenye mkataba anawajibika kwa utunzaji na ukuzaji wa endelevu wa mishipa, na anapata asilimia fulani ya tija ya mishipa</li><li><strong>Mkataba wa Mashamba ya Dawa</strong>: Kutoa mashamba ya dawa ya umma kwa waozaji wenye uwezo wa kilimo kwa mkataba, ambapo mwenye mkataba anawajibika kwa kilimo na utunzaji wa dawa za roho, na mavuno yanagawanywa kwa uwiano</li><li><strong>Usimamizi wa Maeneo ya Siri</strong>: Kumweka maeneo ya siri ya uozi ya umma kwa timu za wataalamu kwa usimamizi, ambapo msimamizi anawajibika kwa utunzaji na usalama wa maeneo, na mtumiaji analipa ada ya matumizi yenye busara</li><li><strong>Uchunguzi wa Rasilimali</strong>: Kuwashawishi waozaji kushiriki katika uchunguzi wa rasilimali katika maeneo yasiyojengwa, ambapo mchunguzi ana haki ya kipaumbele ya mkataba kwa rasilimali mpya zilizogunduliwa</li></ul><h3 id="_4-2-mfumo-wa-ubadilishaji-wa-thamani-ya-mchango" tabindex="-1">4.2 Mfumo wa Ubadilishaji wa Thamani ya Mchango <a class="header-anchor" href="#_4-2-mfumo-wa-ubadilishaji-wa-thamani-ya-mchango" aria-label="Permalink to &quot;4.2 Mfumo wa Ubadilishaji wa Thamani ya Mchango&quot;">​</a></h3><p>Utamaduni wa usawa umeanzisha &quot;Mfumo wa Ubadilishaji wa Thamani ya Mchango&quot; uliounganishwa, ambapo waozaji wanaweza kukusanya thamani ya mchango kwa kutoa mchango kwa mtandao wa usawa, na kisha kutumia thamani ya mchango kubadilisha rasilimali anuwai za uozi:</p><ul><li>Njia za kupata thamani ya mchango zinajumuisha: maendeleo ya uozi, kushiriki maarifa, ubunifu wa teknolojia, huduma za umma, urejeshaji wa ikolojia, ulinzi wa utamaduni, n.k.</li><li>Mfumo wa ubadilishaji unatekeleza &quot;bei wazi&quot;, kila rasilimali ina bei ya thamani ya mchango iliyo wazi, na bei inarekebishwa kwa nguvu kulingana na nadra na mahitaji ya rasilimali</li><li>Mfumo wa ubadilishaji unasaidia kazi ya &quot;malipo mapema&quot; — waozaji wenye uwezo wanaweza kukopesha kiwango fulani cha thamani ya mchango kwa ajili ya ubadilishaji wa rasilimali, na kulipa katika siku zijazo kwa kutoa mchango</li><li>Mfumo wa ubadilishaji ununganishwa kwa wakati halisi na mtandao wa neo, kuhakikisha usajili wa thamani ya mchango na ubadilishaji kuwa salama na wa kuaminika</li></ul><h3 id="_4-3-mfumo-wa-ufunguo-wa-bure-wa-rasilimali-za-umma" tabindex="-1">4.3 Mfumo wa Ufunguo wa Bure wa Rasilimali za Umma <a class="header-anchor" href="#_4-3-mfumo-wa-ufunguo-wa-bure-wa-rasilimali-za-umma" aria-label="Permalink to &quot;4.3 Mfumo wa Ufunguo wa Bure wa Rasilimali za Umma&quot;">​</a></h3><p>Aina zifuatazo za rasilimali zinafunguliwa bure kwa maisha yote:</p><ul><li><strong>Rasilimali za Maarifa</strong>: Mbinu za msingi za mifumo tatu mia ya uozi, uzoefu wa uozi wa umma, nyenzo za msingi za utafiti wa sheria, n.k.</li><li><strong>Rasilimali za Nishati ya Kiwango cha 1</strong>: Nishati ya roho ya msingi, kristali za nishati za kawaida, na rasilimali nyingine za nishati ya kiwango cha chini zilizenea sana</li><li><strong>Nafasi za Uozi za Umma</strong>: Vyumba vya uozi vya umma, vyumba vya msingi vya ufahamu wa sheria, nafasi za kawaida zilizotengwa, n.k.</li><li><strong>Rasilimali za Matibabu ya Msingi</strong>: Mbinu za msingi za matibabu, vidonge vya kawaida vya matibabu ya majeraha, huduma za msingi za urejeshaji, n.k.</li><li><strong>Rasilimali za Elimu ya Msingi</strong>: Kozi za msingi za uozi, mwongozo wa mwalimu wa kuanzia, matumizi ya vifaa vya kawaida vya uozi, n.k.</li></ul><h3 id="_4-4-mfumo-wa-mgawanyo-wa-mwelekeo-wa-rasilimali-maalum" tabindex="-1">4.4 Mfumo wa Mgawanyo wa Mwelekeo wa Rasilimali Maalum <a class="header-anchor" href="#_4-4-mfumo-wa-mgawanyo-wa-mwelekeo-wa-rasilimali-maalum" aria-label="Permalink to &quot;4.4 Mfumo wa Mgawanyo wa Mwelekeo wa Rasilimali Maalum&quot;">​</a></h3><p>Kwa rasilimali za nadra kama vile kiwango cha 4 na cha 5, inatekelezwa mfumo wa &quot;mgawanyo wa mwelekeo&quot;:</p><ul><li>Rasilimali za nadra zinagawanywa kwa kipaumbele kwa miradi muhimu ya kiwango cha utamaduni (kama vile ujenzi wa neo, ukuzaji wa ulimwengu, ushindi wa teknolojia, n.k.)</li><li>Kwa watu binafsi wenye mahitaji maalum (kama vile kuhitaji rasilimali fulani kuvunja kiwango muhimu, kuhitaji dawa nadra kutibu majeraha maalum, n.k.), wanaweza kupata mgawanyo wa mwelekeo kupitia ombi la idhini</li><li>Mpango wa mgawanyo wa rasilimali za nadra unaandaliwa na &quot;Kamiti ya Mgawanyo wa Rasilimali&quot; chini ya Bunge la Jamhuri ya Kila Kabila, na inatekelezwa baada ya uidhinishwe na bunge</li><li>Matokeo ya mgawanyo wa mwelekeo yanafichuliwa kwa jamii na yanakubali ufuatiliaji</li></ul><h2 id="_5-uumbaji-wa-rasilimali-na-maendeleo-ya-endelevu" tabindex="-1">5. Uumbaji wa Rasilimali na Maendeleo ya Endelevu <a class="header-anchor" href="#_5-uumbaji-wa-rasilimali-na-maendeleo-ya-endelevu" aria-label="Permalink to &quot;5. Uumbaji wa Rasilimali na Maendeleo ya Endelevu&quot;">​</a></h2><p>Ufunguo wa rasilimali za uozi sio tu &quot;mgawanyo wa hazina zilizopo&quot;, bali pia &quot;uumbaji wa ongezeko&quot;. Utamaduni wa usawa unashawishi kwa nguvu uumbaji wa kiwango cha kiwandani na ukuzaji wa endelevu wa rasilimali:</p><h3 id="_5-1-kilimo-cha-kiwango-cha-kiwandani-cha-rasilimali" tabindex="-1">5.1 Kilimo cha Kiwango cha Kiwandani cha Rasilimali <a class="header-anchor" href="#_5-1-kilimo-cha-kiwango-cha-kiwandani-cha-rasilimali" aria-label="Permalink to &quot;5.1 Kilimo cha Kiwango cha Kiwandani cha Rasilimali&quot;">​</a></h3><ul><li><strong>Kilimo cha Kiwango cha Kiwandani cha Dawa za Roho</strong>: Kupitia teknolojia ya uhandisi wa sheria, kulima dawa anuwai za roho katika mazingira ya kiwandani, kupunguza utegemezi wa dawa za roho za mwitu</li><li><strong>Uzalishaji wa Kiwango cha Kiwandani cha Nishati</strong>: Kupitia teknolojia kama vile vifaa vya ubadilishaji wa nishati ya vifaa, jenereta za mtiririko wa sheria, kuzalisha kwa kiwandani nishati ya roho na kristali za nishati</li><li><strong>Kuzalisha kwa Kiwango cha Kiwandani Wanyama wa Roho</strong>: Kuanzisha vituo vya kuzalisha wanyama wa roho, kulea kwa kiwandani wanyama anuwai wa roho, kulinda idadi ya wanyama wa roho wa mwitu</li><li><strong>Kujenga kwa Kiwango cha Kiwandani Maeneo ya Siri</strong>: Kupitia teknolojia ya sheria ya nafasi, kujenga kwa kiwandani maeneo ya siri ya uozi, kuongeza ugavi wa nafasi za uozi</li></ul><h3 id="_5-2-matumizi-ya-mzunguko-wa-rasilimali" tabindex="-1">5.2 Matumizi ya Mzunguko wa Rasilimali <a class="header-anchor" href="#_5-2-matumizi-ya-mzunguko-wa-rasilimali" aria-label="Permalink to &quot;5.2 Matumizi ya Mzunguko wa Rasilimali&quot;">​</a></h3><ul><li><strong>Urejeshaji wa Nishati</strong>: Kuanzisha mfumo wa urejeshaji wa nishati, kurejesha na kutumia tena nishati iliyopotea katika mchakato wa uozi, nishati iliyotawanyika katika vita, n.k.</li><li><strong>Usindikaji wa Mabaki ya Dawa</strong>: Kufanya uchambuzi wa pili na usindikaji wa mabaki ya dawa baada ya utengenezaji wa vidonge, kuongeza kiwango cha matumizi ya rasilimali za dawa</li><li><strong>Urejeshaji na Ujenzi upya wa Vifaa</strong>: Kurejesha na kujenga upya vifaa vya uozi vilivyotupwa, kupunguza kupoteza kwa vifaa</li><li><strong>Matumizi ya Mzunguko wa Nafasi</strong>: Kusafisha na kutumia tena kwa mzunguko nafasi zilizotengwa zilizotumika, nafasi za muda za uozi, n.k.</li></ul><h3 id="_5-3-teknolojia-ya-mbadala-wa-rasilimali" tabindex="-1">5.3 Teknolojia ya Mbadala wa Rasilimali <a class="header-anchor" href="#_5-3-teknolojia-ya-mbadala-wa-rasilimali" aria-label="Permalink to &quot;5.3 Teknolojia ya Mbadala wa Rasilimali&quot;">​</a></h3><ul><li>Kushawishi utafiti na ukuzaji wa vipengele vya mbadala kwa rasilimali za nadra, kupitia njia za teknolojia kutekeleza &quot;kubadilisha vifaa vya nadra kwa vifaa vya kawaida&quot;</li><li>Kwa rasilimali za kiwango cha hadithi zisizoweza kuzaliwa upya, kuandaa mipango ya kuzingatia na matumizi kali, na kwa wakati huo huo kuongeza uwekezaji katika utafiti na ukuzaji wa teknolojia ya mbadala</li><li>Kuanzisha &quot;Mfuko wa Utafiti na Ukuzaji wa Teknolojia ya Mbadala wa Rasilimali&quot;, kufadhili miradi inayohusiana na utafiti</li></ul><h2 id="_6-ufuatiliaji-na-usaidizi-wa-ufunguo-wa-rasilimali" tabindex="-1">6. Ufuatiliaji na Usaidizi wa Ufunguo wa Rasilimali <a class="header-anchor" href="#_6-ufuatiliaji-na-usaidizi-wa-ufunguo-wa-rasilimali" aria-label="Permalink to &quot;6. Ufuatiliaji na Usaidizi wa Ufunguo wa Rasilimali&quot;">​</a></h2><h3 id="_6-1-mfumo-wa-ufuatiliaji" tabindex="-1">6.1 Mfumo wa Ufuatiliaji <a class="header-anchor" href="#_6-1-mfumo-wa-ufuatiliaji" aria-label="Permalink to &quot;6.1 Mfumo wa Ufuatiliaji&quot;">​</a></h3><ul><li><strong>Ufuatiliaji wa Wakati Halisi wa Mtandao wa Neo</strong>: Mtandao wa neo unafuatilia wakati halisi ukuzaji, mgawanyo, na matumizi ya rasilimali zote za umma, na anapogundua kushukuma anatoa onyo kwa wakati</li><li><strong>Kamiti ya Haki ya Rasilimali</strong>: Inatutikia hasa ufuatiliaji wa haki na kisheria wa mgawanyo wa rasilimali, na inapokea malalamiko na taarifa</li><li><strong>Ufuatiliaji wa Jamii</strong>: Kuwashawishi maisha yote kufuatilia na kuripoti tabia zisizofaa katika ukuzaji na mgawanyo wa rasilimali</li><li><strong>Ukaguzi wa Mara kwa Mara</strong>: Kila mwaka kufanya ukaguzi wa uhuru kwa mashirika ya usimamizi wa rasilimali, na matokeo ya ukaguzi yanafichuliwa kwa jamii</li></ul><h3 id="_6-2-mfumo-wa-usaidizi" tabindex="-1">6.2 Mfumo wa Usaidizi <a class="header-anchor" href="#_6-2-mfumo-wa-usaidizi" aria-label="Permalink to &quot;6.2 Mfumo wa Usaidizi&quot;">​</a></h3><ul><li><strong>Maombi ya Mgawanyo</strong>: Watu binafsi wenye pingamizi dhidi ya matokeo ya mgawanyo wa rasilimali wanaweza kuomba tathmini upya kwa Kamiti ya Haki ya Rasilimali</li><li><strong>Hakamu ya Mizozo ya Rasilimali</strong>: Mizozo ya rasilimali inahakamishwa na Mahakama ya Neo, na matokeo ya hakamu yana athari ya kisheria</li><li><strong>Usaidizi wa Kukabiliwa na Uonevu</strong>: Watu binafsi walioathirika na tabia kama vile monopoli ya rasilimali, uwindaji wa rasilimali, n.k. wanaweza kuwasilisha kesi Mahakamani ya Neo kudai fidia</li><li><strong>Usaidizi wa Dharura</strong>: Katika hali maalum (kama vile majanga, vita, n.k.), kuanzisha mfumo wa mgawanyo wa dharura wa rasilimali, kuhakikisha mahitaji ya msingi ya rasilimali ya vikundi vilivyoathiriwa</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Utaratibu wa ufunguo wa rasilimali za uozi ni msingi wa mfumo wa kiuchumi wa Utamaduni wa Usawa wa Neo. Kupitia kanuni tano za &quot;uhakikisho wa msingi + kazi nyingi faida nyingi + kupinga monopoli + endelevu + ufunguo uwazi&quot;, inajenga mfumo wa mgawanyo wa rasilimali wenye haki, ufanisi, na endelevu. Lengo la hatima la utaratibu wa ufunguo wa rasilimali sio kufanya maisha yote kupata kiwango sawa cha rasilimali, bali kutoa kila maisha nafasi ya haki ya kupata rasilimali, kufanya rasilimali zimiririke mahali pengine zenye uwezo wa kuunda thamani zaidi, na kufanya jumla ya rasilimali ya utamaduni iendelee kukua chini ya masharti ya endelevu. Wakati rasilimali za uozi zisikuwa tena mali ya kibinafsi inayokabiliwa na watu wachache, bali kuwa mali ya umma inayoshirikishwa na kila kabila na inapata faida ya mzunguko, ndipo bora la &quot;kila mtu ana njii&quot; linaweza kutimizwa kwa kweli, na lengo la maendeleo ya pamoja ya kila kabila linaweza kufikiwa kwa kweli.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Kanuni ya Mgawanyo wa Kazi Nyingi Faida Nyingi)</li><li>08-人人有路保障体系 (Mfumo wa Uhakikisho wa Kila Mtu Ana Njia)</li><li>22-资源分配联产承包机制 (Mfumo wa Mkataba wa Uzalishaji Pamoja wa Mgawanyo wa Rasilimali)</li></ul>',57)])])}const z=i(o,[["render",m]]);export{r as __pageData,z as default};
